"""The Tiffinbell city dashboard, as it runs today. Do not edit this file.

QUERIES holds the three tiles of the dashboard, exactly as the dashboard runs
them. Each one takes named parameters (:customer_id, :day, :month).
EXAMPLE_PARAMS holds one set of values for each tile.
EXISTING_INDEXES is what the orders database has today: one index, added two
weeks ago "to speed up the dashboard".

open_db() loads data/*.csv into an in-memory SQLite database with the
existing indexes, the same way the test does. Stdlib only.
"""
import csv
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))

QUERIES = {
    # Tile 1: the last 10 orders of one customer, for the support team.
    "customer_history": """
SELECT order_id, ordered_at, amount, status
FROM orders
WHERE customer_id = :customer_id
ORDER BY ordered_at DESC, order_id DESC
LIMIT 10""",
    # Tile 2: completed orders and revenue on one day.
    "day_summary": """
SELECT COUNT(*) AS orders, SUM(amount) AS revenue
FROM orders
WHERE date(ordered_at) = :day
  AND status = 'completed'""",
    # Tile 3: completed orders and revenue by city for one month.
    "city_month": """
SELECT c.city, COUNT(*) AS orders, SUM(o.amount) AS revenue
FROM orders o
JOIN customers c ON c.customer_id = o.customer_id
WHERE strftime('%Y-%m', o.ordered_at) = :month
  AND o.status = 'completed'
GROUP BY c.city
ORDER BY revenue DESC, c.city""",
}

EXAMPLE_PARAMS = {
    "customer_history": {"customer_id": "T00007"},
    "day_summary": {"day": "2026-10-17"},
    "city_month": {"month": "2026-10"},
}

EXISTING_INDEXES = ["CREATE INDEX ix_orders_status ON orders (status)"]

COLUMNS = {"customers": ["customer_id", "city", "joined_on"],
           "orders": ["order_id", "customer_id", "ordered_at", "amount", "status"]}


def cast(value):
    if value is None or value == "":
        return None
    for kind in (int, float):
        try:
            return kind(value)
        except ValueError:
            pass
    return value


def read_csv_tables(data_dir=os.path.join(HERE, "data")):
    tables = {}
    for name in COLUMNS:
        with open(os.path.join(data_dir, name + ".csv"), newline="") as f:
            tables[name] = [{k: cast(v) for k, v in row.items()} for row in csv.DictReader(f)]
    return tables


def open_db(tables=None, indexes=EXISTING_INDEXES):
    """An in-memory database of the tables (default: data/*.csv) with the given indexes."""
    if tables is None:
        tables = read_csv_tables()
    con = sqlite3.connect(":memory:")
    for name, cols in COLUMNS.items():
        con.execute("CREATE TABLE %s (%s)" % (name, ", ".join(cols)))
        con.executemany("INSERT INTO %s VALUES (%s)" % (name, ", ".join("?" * len(cols))),
                        [[r.get(c) for c in cols] for r in tables.get(name, [])])
    for sql in indexes:
        con.execute(sql)
    return con
